class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        if k == 1:
            # For length 1, any single character works if it's surrounded by different characters
            # We can just check if the first and last characters are different
            if n >= 2:
                return s[0] != s[1]
            else:
                # Single char string with k=1: no neighbors to check
                return False

        # Check windows of length k
        for i in range(n - k + 1):
            char = s[i]
            # Check if substring of length k consists of only one distinct character
            if len(set(s[i:i+k])) == 1:
                # Check character before
                if i > 0 and s[i-1] == char:
                    continue
                # Check character after
                if i + k < n and s[i+k] == char:
                    continue
                # If we reach here, a valid substring exists
                return True
        return False
